    """Convert Roman numeral string to integer.
    Handles standard symbols I V X L C D M with subtractive notation.
    """
    values = {'I':1,'V':5,'X':10,'L':50,'C':100,'D':500,'M':1000}
    total = 0
    prev = 0
    # Process from right to left: subtract if current value less than previous max.
    for ch in reversed(s):
        val = values[ch]
        if val < prev:
            total -= val
        else:
            total += val
            prev = val
    return total

