def solve(a, b):
    # Ensure a is the shorter string to use less space
    if len(a) > len(b):
        a, b = b, a
    n, m = len(a), len(b)
    # previous row
    prev = list(range(n + 1))
    for j in range(1, m + 1):
        cur = [j] + [0] * n
        bj = b[j - 1]
        for i in range(1, n + 1):
            if a[i - 1] == bj:
                cur[i] = prev[i - 1]
            else:
                cur[i] = 1 + min(prev[i],      # deletion (from b)
