    """Return length of longest strictly increasing subsequence.
    Uses patience sorting with binary search, O(n log n).
    """
    import bisect
    if not nums:
        return 0
    tails = []  # tails[i] = smallest ending value of an increasing subseq of length i+1
    for x in nums:
        # find insertion point (first >= x) because we need strictly increasing, so use bisect_left
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
