def solve(a, b):
    """Levenshtein distance between strings a and b.
    Uses dynamic programming with O(min(n,m)) space.
    """
    if len(a) > len(b):
        a, b = b, a
    n, m = len(a), len(b)
    dp = list(range(m + 1))
    for i in range(1, n + 1):
        prev = dp[0]
        dp[0] = i
        for j in range(1, m + 1):
            cur = dp[j]
            if a[i - 1] == b[j - 1]:
                dp[j] = prev
            else:
                dp[j] = 1 + min(prev, dp[j], dp[j - 1])
            prev = cur
    return dp[m]

