def solve(nums):
    # Returns length of longest strictly increasing subsequence
    if not nums:
        return 0
    tails = []  # tails[i] = smallest possible tail of an increasing subseq of length i+1
    for x in nums:
        # Find insertion point for x in tails to maintain strictly increasing
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)
"}

